#[path="../src/app_defaults.rs"]mod app_defaults;
use app_defaults::*;
#[test]fn roundtrip_replace_reset_and_extensionless(){let mut t=Table::new();t.set(b"txt",Some(b"note")).unwrap();t.set(b"-",Some(b"viewer")).unwrap();assert_eq!(t.get(b"TXT"),Some(&b"NOTE"[..]));assert_eq!(t.get(b""),Some(&b"VIEWER"[..]));t.set(b"TXT",Some(b"OTHER")).unwrap();let mut b=[0;MAX_BYTES];let n=t.encode(&mut b);let mut t=Table::parse(&b[..n]).unwrap();assert_eq!(t.get(b"txt"),Some(&b"OTHER"[..]));t.set(b"txt",None).unwrap();assert_eq!(t.get(b"TXT"),None);assert_eq!(t.get(b"-"),Some(&b"VIEWER"[..]));}
#[test]fn unsafe_and_executable_preferences_refused(){for ext in [b"BIN" as &[u8],b"elf",b"",b"LONG",b"../",b"A B",b"A=B"]{assert!(!extension(ext));assert!(Table::new().set(ext,Some(b"APP")).is_err());}for id in [b"/APP" as &[u8],b"..",b"1APP",b"TOOLONGID",b"APP.BIN",b"APP ARG",b""]{assert!(Table::new().set(b"TXT",Some(id)).is_err());}}
#[test]fn malformed_duplicate_and_oversized_files_refused(){for b in [b"garbage" as &[u8],b"XINYI-DEFAULTS 1\nTXT=A",b"XINYI-DEFAULTS 1\nTXT=A\ntxt=B\n",b"XINYI-DEFAULTS 1\nTXT=../BAD\n",b"XINYI-DEFAULTS 1\nBIN=APP\n"]{assert!(Table::parse(b).is_err());}assert!(Table::parse(&[b'A';257]).is_err());}
#[test]fn maximum_capacity_and_reuse(){let mut t=Table::new();for n in 0..16 {let e=[b'A',b'A'+n];t.set(&e,Some(b"ABCDEFGH")).unwrap();}assert!(t.set(b"ZZ",Some(b"APP")).is_err());let mut b=[0;MAX_BYTES];let n=t.encode(&mut b);assert!(n<=MAX_BYTES);assert!(Table::parse(&b[..n]).is_ok());t.set(b"AA",None).unwrap();t.set(b"ZZ",Some(b"APP")).unwrap();assert_eq!(t.get(b"ZZ"),Some(&b"APP"[..]));}
